const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',timer:'<circle cx="12" cy="13" r="8"/><path d="M12 9v4l2 2M9 2h6M12 2v3M18 5l2 2"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18M7 14h3M14 14h3M7 17h3"/>',book:'<path d="M12 5c-3-2-6-2-10-1v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-1-10 1Zm0 0v15"/>',note:'<path d="M14 3H5a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-9M9 15l1-4L19 2l3 3-9 9-4 1Z"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',leaf:'<path d="M20 3C10 2 3 6 4 13c1 8 13 9 16-10ZM4 21c3-7 6-11 11-14"/>',settings:'<path d="m10 3-.7 2.2-2.1 1L5 5.7 2.7 9l1.6 1.8v2.4L2.7 15 5 18.3l2.2-.5 2.1 1L10 21h4l.7-2.2 2.1-1 2.2.5 2.3-3.3-1.6-1.8v-2.4L21.3 9 19 5.7l-2.2.5-2.1-1L14 3Z"/><circle cx="12" cy="12" r="3"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1.5 1.5M17.5 17.5 1.5 1.5M19 5l-1.5 1.5M6.5 17.5 5 19"/>',moon:'<path d="M20 15A9 9 0 0 1 9 3a9 9 0 1 0 11 12Z"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M4 12h16M15 7l5 5-5 5"/>',play:'<path d="m8 5 11 7-11 7Z"/>',pause:'<path d="M8 5v14M16 5v14"/>',reset:'<path d="M3 10a9 9 0 1 1 1 8M3 4v6h6"/>',check:'<path d="m5 12 4 4L19 6"/>',flame:'<path d="M12 2c1 5-5 5-5 10-2-1-3-2-3-3-3 8 1 13 8 13 7 0 11-9 5-14 1 5-2 6-3 4 2-4 0-7-2-10Z"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',trend:'<path d="m3 17 6-6 4 4 8-10M15 5h6v6"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',trash:'<path d="M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',building:'<path d="m2 8 10-5 10 5H2ZM3 21h18M5 11v7M10 11v7M14 11v7M19 11v7"/>',drop:'<path d="M12 2C9 7 5 10 5 15a7 7 0 0 0 14 0c0-5-4-8-7-13Z"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',coffee:'<path d="M3 5h13v8a6 6 0 0 1-12 0V5ZM16 6h2a3 3 0 0 1 0 6h-2M2 21h17"/>',pen:'<path d="m3 21 4-1 14-14-3-3L4 17l-1 4ZM15 6l3 3M12 21h9"/>'};
